// PC port: the other region's player sprites, for a visiting trainer
// (shared/pc_travel.c). The data is generated by tools/gen_visitor_gfx.py
// from the other decomp; its sheets and palettes are cartridge content that
// comes from the player's own copy of the other game (the foreign pack,
// tools/rompack.c --foreign).
#ifndef GUARD_PC_VISITOR_GFX_H
#define GUARD_PC_VISITOR_GFX_H

enum {
    PC_VISITOR_NORMAL,      // walking and running
    PC_VISITOR_BIKE,
    PC_VISITOR_SURF,
    PC_VISITOR_FIELD_MOVE,
    PC_VISITOR_FISH,
    PC_VISITOR_STATE_COUNT
};

struct PcVisitorState
{
    const struct SpriteFrameImage *images;
    const union AnimCmd *const *anims;
    u16 animCount;
    u16 size;
    u8 width, height;
};

extern const struct PcVisitorState gPcVisitorStates[2][PC_VISITOR_STATE_COUNT];  // [gender]
extern const u16 gPcVisitorPal[4][16];   // [gender * 2]: the sprites', [gender * 2 + 1]: their reflection's

// their palettes, beside the game's own (event_object_movement.c)
#define PC_VISITOR_PAL_TAG(gender)            (0x11F0 + (gender) * 2)
#define PC_VISITOR_REFLECTION_PAL_TAG(gender) (0x11F1 + (gender) * 2)

#endif // GUARD_PC_VISITOR_GFX_H
